// === Tab: mySketch ===
let points = []; 
let numWedges = 6;

function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(DEGREES);
  // noLoop() removed for animation
}

function draw() {
  background(color(255,0,0));
  translate(width / 2, height / 2); 

  let wedgeAngle = 360 / numWedges;

  for (let i = 0; i < numWedges; i++) {
    push();
    rotate(i * wedgeAngle);

    drawSegment();

    scale(1, -1);
    drawSegment();

    pop();
  }
}

function mouseDragged() {
  let x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2;
  let y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2;
	//stroke(color(random(0,255),random(0,255),random(0,255)))
  points.push({ x: x, y: y });
  redraw();
}

function drawSegment() {
  stroke(255);
  strokeWeight(2);
  noFill();

  beginShape();
  for (let pt of points) {
    vertex(pt.x, pt.y);
  }
  endShape();
}

function keyPressed(){
	if(key===" "){
		clear();
		points=[];
	}
}
